pm.test('Invito inviato', () => pm.expect(j.invitation.status).to.eql('sent'));
if (j.invitation.status !== 'sent' || !j.invitation.reset_url) { pm.execution.setNextRequest(null); throw new Error('Utente creato: per la prova automatica serve APP_ENV=local, APP_DEBUG=true, AUTH_EXPOSE_RESET_URL=true e MAIL_MAILER=log. Il link è anche nel log email. Non ricreare lo stesso account.'); }
const invitationQuery = Object.fromEntries(j.invitation.reset_url.split('?')[1].split('&').map(p => {const [k,v]=p.split('='); return [decodeURIComponent(k),decodeURIComponent(v.replace(/\+/g,' '))];}));
if (invitationQuery.email !== pm.collectionVariables.get('test_email') || !invitationQuery.token) { pm.execution.setNextRequest(null); throw new Error('Invito non associato al demo.'); }
pm.collectionVariables.set('invitation_token', invitationQuery.token);
